// Where a started prototype runs, for a persona test: its address once it
// answers, on the page it opens on; refused, saying why, when it does not
// start.
import { Refused } from "../../refused.js";
import { running } from "./looks.js";
import { shownAddress } from "./versions.js";
export async function addressOf(mode, exploration, key, made) {
    const url = await running(mode, exploration, key).catch((error) => {
        throw new Refused(`Prototype ${key} did not start: ${error instanceof Error ? error.message : String(error)}`);
    });
    return shownAddress(url, made);
}
